-- Sim-native telemetry ingest (docs/sim-native-telemetry.md §3, §5.1). Runs alongside the
-- flight_track_points upload path until the web reads derived products.

-- Channel tables, stored once under the SHA-256 of their encoded bytes, so a client can
-- add channels without a service deploy.
CREATE TABLE IF NOT EXISTS telemetry_schemas (
    hash       BYTEA PRIMARY KEY,
    channels   BYTEA NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- One continuous connection to one sim with one aircraft loaded. The id is generated by
-- the client, so a session can be spooled before it is acknowledged and opening it again
-- is a no-op.
CREATE TABLE IF NOT EXISTS telemetry_sessions (
    id               UUID PRIMARY KEY,
    user_id          BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    schema_hash      BYTEA NOT NULL REFERENCES telemetry_schemas(hash),
    -- The session opening as received: header and channel table. Kept whole because the
    -- compacted segment carries it.
    open_blob        BYTEA NOT NULL,
    protocol_version INTEGER NOT NULL,
    sim              TEXT NOT NULL,
    sim_version      TEXT NOT NULL,
    capture          TEXT NOT NULL,
    client_version   TEXT NOT NULL,
    aircraft         JSONB NOT NULL,
    -- open: receiving chunks. ended: the client said so, or it went silent; compacted once
    -- every chunk is in. compacted: chunks moved to one segment object in R2.
    status           TEXT NOT NULL DEFAULT 'open',
    end_reason       TEXT,
    -- Chunks below this were received and decoded in order; the next one to decode.
    next_seq         INTEGER NOT NULL DEFAULT 0,
    -- First chunk that failed to decode in order, which holds next_seq back for good.
    invalid_seq      INTEGER,
    chunk_count      INTEGER NOT NULL DEFAULT 0,
    chunk_bytes      BIGINT NOT NULL DEFAULT 0,
    segment_key      TEXT,
    segment_bytes    BIGINT,
    started_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_chunk_at    TIMESTAMPTZ,
    ended_at         TIMESTAMPTZ,
    compacted_at     TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_telemetry_sessions_user ON telemetry_sessions (user_id, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_telemetry_sessions_status ON telemetry_sessions (status);

-- Chunks of sessions not yet compacted, zstd-compressed as sent. Idempotent by
-- (session_id, seq), as flight_track_points is by sample epoch.
CREATE TABLE IF NOT EXISTS telemetry_chunks (
    session_id  UUID NOT NULL REFERENCES telemetry_sessions(id) ON DELETE CASCADE,
    seq         INTEGER NOT NULL,
    keyframe    BOOLEAN NOT NULL,
    data        BYTEA NOT NULL,
    received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (session_id, seq)
);
